import json
with open('/tmp/dev_data_200.json') as f:
    data = json.load(f)

for topic in ['algebra', 'geometry']:
    q_topic = [q for q in data if q['topic'] == topic]
    # In each question, check the scores:
    # 1. Plain majority: count(a)
    # 2. Distinct variants: len(variants(a))
    # 3. What if we filter out scores > 2.0?
    # 4. What if we use a scoring function: e.g. sum(1 for s in samples if -0.2 <= score <= 1.8)?

    # Let's test a few ranking functions on all 10 samples:
    def rank_cv(samples):
        # Distinct variants count
        var_map = {}
        for s in samples:
            a = s['answer']
            if a not in var_map: var_map[a] = set()
            var_map[a].add(s['variant'])
        return max(var_map.keys(), key=lambda a: (len(var_map[a]), len([s for s in samples if s['answer'] == a])))

    def rank_cv_filter(samples):
        # Filter out samples with score > 2.0 or score < -0.2?
        # Let's see what happens if we only count samples with score in [0.0, 1.8]
        var_map = {}
        valid = [s for s in samples if 0.2 <= s['score'] <= 1.8]
        if not valid:
            valid = samples
        for s in valid:
            a = s['answer']
            if a not in var_map: var_map[a] = set()
            var_map[a].add(s['variant'])
        return max(var_map.keys(), key=lambda a: (len(var_map[a]), len([s for s in valid if s['answer'] == a])))

    corr_maj = sum(1 for q in q_topic if max(set(s['answer'] for s in q['samples']), key=lambda a: sum(1 for s in q['samples'] if s['answer']==a)) == q['correct_answer'])
    corr_cv = sum(1 for q in q_topic if rank_cv(q['samples']) == q['correct_answer'])
    corr_cv_filter = sum(1 for q in q_topic if rank_cv_filter(q['samples']) == q['correct_answer'])

    print(f'{topic}: Plain Maj={corr_maj}/50 ({corr_maj/50:.2f}), CrossVar={corr_cv}/50 ({corr_cv/50:.2f}), FilteredCV={corr_cv_filter}/50 ({corr_cv_filter/50:.2f})')
""]}

