    data = json.load(f)

for topic in ['algebra', 'geometry']:
    print(f'=== {topic} ===')
    q_topic = [q for q in data if q['topic'] == topic]

    # We want to test picking 5 samples per question (1 per variant) vs 8 samples
    # Let's test allocating budget:
    # Say we take 1 sample per variant (v0..v4) -> 5 samples
    # And if any sample looks good (e.g. sweet spot), do we need more?
    # Or what if we sample all 5 variants first (5 samples), and if needed, sample more?

    # Let's test on our dataset: each question has 2 samples for v0..v4 (10 samples total).
    # If we take the first 5 samples (1 per variant):
    import random
    random.seed(42)
    accs = []
    for _ in range(200):
        corr = 0
        for q in q_topic:
            # 1 sample per variant
            samples = [random.choice([s for s in q['samples'] if s['variant'] == v]) for v in range(5)]
            ans_scores = {}
            for s in samples:
                a = s['answer']
                sc = s['score']
                if sc < 0.2:
                    w = 0.0
                elif sc <= 1.2:
                    w = 1.0
                elif sc <= 1.5:
                    w = 1.0 - (sc - 1.2) / 0.3
                else:
                    w = -2.0 * (sc - 1.5)
                ans_scores[a] = ans_scores.get(a, 0.0) + w
            best = max(ans_scores, key=ans_scores.get)
            if best == q['correct_answer']:
                corr += 1
        accs.append(corr / len(q_topic))
    print(f'5 samples (1/var) acc: {sum(accs)/len(accs):.3f}')

    # Now what if we take 8 samples (e.g. 5 variants + 3 more)?
    accs_8 = []
    for _ in range(200):
        corr = 0
        for q in q_topic:
            # 8 samples at random from the 10
            samples = random.sample(q['samples'], 8)
            ans_scores = {}
            for s in samples:
                a = s['answer']
                sc = s['score']
                if sc < 0.2:
                    w = 0.0
                elif sc <= 1.2:
                    w = 1.0
                elif sc <= 1.5:
                    w = 1.0 - (sc - 1.2) / 0.3
                else:
                    w = -2.0 * (sc - 1.5)
                ans_scores[a] = ans_scores.get(a, 0.0) + w
            best = max(ans_scores, key=ans_scores.get)
            if best == q['correct_answer']:
                corr += 1
        accs_8.append(corr / len(q_topic))
    print(f'8 samples acc: {sum(accs_8)/len(accs_8):.3f}')
""]}

