import json
with open('/tmp/dev_data_200.json') as f:
    data = json.load(f)

# Total questions: 200 (50 per topic)
# Let's simulate:
# Topics: combinatorics, number_theory -> 4 samples each (total 400 samples for 100 questions)
# Remaining budget for 100 algebra + geometry: 2400 - 400 = 2000 samples -> 20 samples each!
# But in dev_data_200 we have 10 samples per question.
# Let's simulate what accuracy we get if:
# Comb / NT: take up to 4 samples, stop if score >= 0.7, pick max score
# Alg / Geom: take all 10 samples (or 5, or 8), score with sweet-spot function

def eval_comb_nt(q, max_k=6, thresh=0.7):
    samples = q['samples'][:max_k]
    for s in samples:
        if s['score'] >= thresh:
            return s['answer'] == q['correct_answer'], s['answer']
    best = max(samples, key=lambda s: s['score'])
    return best['answer'] == q['correct_answer'], best['answer']

def eval_alg_geom(q, k=10):
    samples = q['samples'][:k]
    ans_val = {}
    ans_vars = {}
    for s in samples:
        a = s['answer']
        sc = s['score']
        v = s['variant']
        if 0.3 <= sc <= 1.3:
            w = 1.0
        elif sc > 1.6:
            w = -1.0
        else:
            w = 0.0
        ans_val[a] = ans_val.get(a, 0.0) + w
        if a not in ans_vars: ans_vars[a] = set()
        if 0.3 <= sc <= 1.4:
            ans_vars[a].add(v)
