import json

with open('/tmp/dev_data_200.json') as f:
    dev_data = json.load(f)

# 200 questions: 50 algebra, 50 geometry, 50 combinatorics, 50 number_theory
# We want to test a 2-pass policy on this 200-question batch!
# Budget proportional to 200 questions: 200 * 6 = 1200 samples.

def simulate(comb_nt_first_k=3, comb_nt_max_k=7, alg_geom_first_k=5, alg_geom_max_k=9):
    # Pass 1:
    samples_used = 0
    q_state = {}

    for q in dev_data:
        topic = q['topic']
        qid = q['id']
        q_state[qid] = {
            'topic': topic,
            'samples': [],
            'resolved': False,
            'chosen': None,
            'correct_answer': q['correct_answer']
        }

        if topic in ('combinatorics', 'number_theory'):
            # Take up to comb_nt_first_k samples
            for i in range(comb_nt_first_k):
                s = q['samples'][i]
                samples_used += 1
                q_state[qid]['samples'].append(s)
                if s['score'] >= 0.7:
                    q_state[qid]['resolved'] = True
                    q_state[qid]['chosen'] = s['answer']
                    break
        else: # algebra, geometry
            # Take 1 sample per variant up to alg_geom_first_k
            for i in range(alg_geom_first_k):
                s = q['samples'][i]
                samples_used += 1
                q_state[qid]['samples'].append(s)
            # Check if resolved
            ans_vars = {}
            for s in q_state[qid]['samples']:
                if 0.3 <= s['score'] <= 1.3:
                    if s['answer'] not in ans_vars: ans_vars[s['answer']] = set()
                    ans_vars[s['answer']].add(s['variant'])
                    if len(ans_vars[s['answer']]) >= 2:
                        q_state[qid]['resolved'] = True
                        q_state[qid]['chosen'] = s['answer']
                        break

    print(f"Pass 1 finished: samples used = {samples_used} / 1200. Unresolved = {sum(1 for st in q_state.values() if not st['resolved'])}")

    # Pass 2: unresolved questions
    # Priority: combinatorics / number_theory get up to comb_nt_max_k
    # algebra / geometry get up to alg_geom_max_k
    for q in dev_data:
        qid = q['id']
        st = q_state[qid]
        if st['resolved']:
            continue
        topic = st['topic']
        if topic in ('combinatorics', 'number_theory'):
            curr_len = len(st['samples'])
            for i in range(curr_len, min(comb_nt_max_k, len(q['samples']))):
                s = q['samples'][i]
                samples_used += 1
                st['samples'].append(s)
                if s['score'] >= 0.7:
                    st['resolved'] = True
                    st['chosen'] = s['answer']
                    break
            if not st['resolved']:
                # choose max score
                st['chosen'] = max(st['samples'], key=lambda s: s['score'])['answer']
                st['resolved'] = True
        else: # algebra, geometry
            curr_len = len(st['samples'])
            for i in range(curr_len, min(alg_geom_max_k, len(q['samples']))):
                s = q['samples'][i]
                samples_used += 1
                st['samples'].append(s)
            # Evaluate using scoring function
            ans_val = {}
            ans_vars = {}
            for s in st['samples']:
                a = s['answer']
                sc = s['score']
                v = s['variant']
                if 0.3 <= sc <= 1.3:
                    w = 1.0
                elif sc > 1.6:
                    w = -1.0
                else:
                    w = 0.0
                ans_val[a] = ans_val.get(a, 0.0) + w
                if a not in ans_vars: ans_vars[a] = set()
                if 0.3 <= sc <= 1.4:
                    ans_vars[a].add(v)
            best = max(ans_val.keys(), key=lambda a: (ans_val[a], len(ans_vars.get(a, [])), sum(1 for s in st['samples'] if s['answer']==a)))
            st['chosen'] = best
            st['resolved'] = True

    print(f"Pass 2 finished: total samples used = {samples_used} / 1200")

    # Compute accuracy overall and per topic
    correct_by_topic = {}
    total_by_topic = {}
    for st in q_state.values():
        t = st['topic']
        total_by_topic[t] = total_by_topic.get(t, 0) + 1
        if st['chosen'] == st['correct_answer']:
            correct_by_topic[t] = correct_by_topic.get(t, 0) + 1

    overall_acc = sum(correct_by_topic.values()) / len(dev_data)
    print(f"Overall accuracy: {overall_acc:.4f} ({sum(correct_by_topic.values())}/{len(dev_data)})")
    for t in ['algebra', 'geometry', 'combinatorics', 'number_theory']:
        acc = correct_by_topic.get(t, 0) / total_by_topic[t]
        print(f"  {t:15s}: {acc:.4f} ({correct_by_topic.get(t, 0)}/{total_by_topic[t]})")

simulate()
