import json

with open('/tmp/dev_data_200.json') as f:
    dev_data = json.load(f)

for q in dev_data:
    by_var = {}
    for s in q['samples']:
        by_var.setdefault(s['variant'], []).append(s)
    reordered = []
    for rep in range(2):
        for v in range(5):
            reordered.append(by_var[v][rep])
    q['samples'] = reordered

def score_alg_geom(samples):
    ans_val = {}
    ans_vars = {}
    for s in samples:
        a = s['answer']
        sc = s['score']
        v = s['variant']
        if 0.35 <= sc <= 1.35:
            w = 1.0
        elif sc > 1.6:
            w = -1.0
        else:
            w = 0.0
        ans_val[a] = ans_val.get(a, 0.0) + w
        if a not in ans_vars: ans_vars[a] = set()
        if 0.35 <= sc <= 1.45:
            ans_vars[a].add(v)
    return max(ans_val.keys(), key=lambda a: (ans_val[a], len(ans_vars.get(a, set())), sum(1 for s in samples if s['answer']==a)))

def check_alg_geom_early(samples):
    ans_vars = {}
    ans_high = {}
    for s in samples:
        a = s['answer']
        sc = s['score']
        v = s['variant']
        if 0.35 <= sc <= 1.35:
            ans_vars.setdefault(a, set()).add(v)
        elif sc > 1.6:
            ans_high[a] = ans_high.get(a, 0) + 1
    for a, vs in ans_vars.items():
        if len(vs) >= 3 and ans_high.get(a, 0) == 0:
            return a
    return None

budget = 1200
samples_used = 0
q_state = {}
for q in dev_data:
    q_state[q['id']] = {
        'topic': q['topic'],
        'samples': [],
        'resolved': False,
        'chosen': None,
        'correct_answer': q['correct_answer'],
        'raw_samples': q['samples']
    }

# Phase 1: Comb / NT sample up to 8, stop if score >= 0.70
for qid, st in q_state.items():
    if st['topic'] in ('combinatorics', 'number_theory'):
        for i in range(min(8, len(st['raw_samples']))):
            if samples_used >= budget: break
            s = st['raw_samples'][i]
            samples_used += 1
            st['samples'].append(s)
            if s['score'] >= 0.70:
                st['resolved'] = True
                st['chosen'] = s['answer']
                break

# Phase 2: Alg / Geom initial 5 samples (variants 0..4)
for qid, st in q_state.items():
    if st['topic'] in ('algebra', 'geometry'):
        for i in range(min(5, len(st['raw_samples']))):
            if samples_used >= budget: break
            s = st['raw_samples'][i]
            samples_used += 1
            st['samples'].append(s)
        cand = check_alg_geom_early(st['samples'])
        if cand is not None:
            st['resolved'] = True
            st['chosen'] = cand

# Phase 3: Round robin for unresolved Alg / Geom
while samples_used < budget:
    added = False
    for qid, st in q_state.items():
        if samples_used >= budget: break
        if st['topic'] in ('algebra', 'geometry') and not st['resolved'] and len(st['samples']) < len(st['raw_samples']):
            curr_idx = len(st['samples'])
            s = st['raw_samples'][curr_idx]
            samples_used += 1
            st['samples'].append(s)
            added = True
            cand = check_alg_geom_early(st['samples'])
            if cand is not None:
                st['resolved'] = True
                st['chosen'] = cand
    if not added:
        break

# Phase 4: Any remaining budget to unresolved Comb / NT
while samples_used < budget:
    added = False
    for qid, st in q_state.items():
        if samples_used >= budget: break
        if st['topic'] in ('combinatorics', 'number_theory') and not st['resolved'] and len(st['samples']) < len(st['raw_samples']):
            curr_idx = len(st['samples'])
            s = st['raw_samples'][curr_idx]
            samples_used += 1
            st['samples'].append(s)
            added = True
            if s['score'] >= 0.70:
                st['resolved'] = True
                st['chosen'] = s['answer']
    if not added:
        break

# Phase 5: Any remaining budget to any question with < 10 samples
while samples_used < budget:
    added = False
    for qid, st in q_state.items():
        if samples_used >= budget: break
        if not st['resolved'] and len(st['samples']) < len(st['raw_samples']):
            curr_idx = len(st['samples'])
            s = st['raw_samples'][curr_idx]
            samples_used += 1
            st['samples'].append(s)
            added = True
    if not added:
        break

# Final decisions
for qid, st in q_state.items():
    if not st['resolved']:
        if st['topic'] in ('combinatorics', 'number_theory'):
            st['chosen'] = max(st['samples'], key=lambda s: s['score'])['answer']
        else:
            st['chosen'] = score_alg_geom(st['samples'])
        st['resolved'] = True

correct = sum(1 for st in q_state.values() if st['chosen'] == st['correct_answer'])
print(f"Total used: {samples_used}/{budget}, acc={correct/200:.4f}")
for t in ['algebra', 'geometry', 'combinatorics', 'number_theory']:
    t_corr = sum(1 for st in q_state.values() if st['topic'] == t and st['chosen'] == st['correct_answer'])
    print(f"   {t:15s}: {t_corr}/50 ({t_corr/50:.2f})")
